22: function loadGame() {
23:   try {
24:     const saved = JSON.parse(localStorage.getItem(SAVE))
25:     if (saved?.creatures?.length) {
26:       saved.creatures.forEach(c => { c.needs ||= freshNeeds(78); c.wins ||= 0; c.battles ||= 0; c.born ||= Date.now() })
27:       return { creatures: saved.creatures, selected: saved.selected || saved.creatures[0].id, coins: saved.coins ?? 120, food: saved.food ?? 8, wins: saved.wins ?? 0, archives: Array.isArray(saved.archives) ? saved.archives : [] }
28:     }
29:   } catch (e) { console.warn('Save could not be loaded', e) }
30:   const creatures = [
31:     generateStarter(401, { hueA: .73, hueB: .22, horns: .76, muscle: .64, size: .58, brain: .45, speed: .56 }),
32:     generateStarter(908, { hueA: .12, hueB: .83, wings: .81, speed: .74, brain: .68, horns: .25, size: .42 }),
33:     generateStarter(173, { hueA: .47, hueB: .1, armor: .79, bone: .78, size: .77, muscle: .55, wings: .1 }),
34:   ]
35:   ;['Cinderhorn', 'Glimmerwing', 'Mossback'].forEach((n, i) => { creatures[i].name = n; creatures[i].needs = freshNeeds(86 - i * 5) })
36:   return { creatures, selected: creatures[0].id, coins: 120, food: 8, wins: 0, archives: [] }
37: }
38: const game = loadGame()
39: let mode = 'habitat', tab = 'overview', world, battle = null, toastTimer
40: const app = $('#app')
41: app.innerHTML = `
42: <div class="shell">
43: <header class="topbar"><a class="brand" href="#"><span class="brand-mark">H<span>↗</span></span><span class="brand-copy">HELIX<span>FORGE</span></span></a><div class="top-status"><i class="live-dot"></i> GENOME SANCTUARY <span class="season">SEASON 01 · THE VERDANT</span></div><div class="resources"><div class="resource"><span>✧</span><b id="coins">120</b><small>SHARDS</small></div><div class="resource"><span>◉</span><b id="food">8</b><small>NECTAR</small></div></div></header>
44: <main class="workspace">
45: <aside class="left-rail"><div class="section-label">YOUR SANCTUARY <span id="roster-count">03</span></div><div class="roster" id="roster"></div><button class="discover" data-action="discover">＋ DISCOVER CREATURE <small>60 ✧</small></button><div class="rail-spacer"></div><div class="sanctuary-card"><div class="sanctuary-orb">✳</div><div><b>THE HOLLOW</b><span>Habitat level 01</span></div><i class="live-tag">LIVE</i><p>Creatures wander, rest and recover here.</p><div class="harmony"><i></i></div><small>SANCTUARY HARMONY <b>78%</b></small></div><div class="rail-footer">BUILD 1.0 · AUTOSAVED</div></aside>
46: <section class="stage-column"><div class="stage-head"><div><div class="eyebrow" id="stage-kicker">◌ OPEN HABITAT</div><h1 id="stage-title">The Verdant Hollow</h1></div><div class="stage-controls"><span class="creature-count"><i></i><b id="stage-count">3</b> CREATURES</span><button class="view-btn active" data-mode="habitat">◉ HABITAT</button><button class="view-btn" data-mode="arena">⚔ ARENA</button></div></div>
47: <div class="viewport-wrap"><div class="viewport" id="viewport"></div><div class="viewport-vignette"></div><div class="scene-tag"><i class="live-dot"></i><span id="scene-tag-text">ECOSYSTEM ACTIVE</span></div><div class="camera-hint">DRAG TO ORBIT <b>·</b> SCROLL TO ZOOM</div><div id="battle-hud" class="battle-hud hidden"></div><div id="battle-result" class="battle-result hidden"></div></div>
48: <div class="stage-bottom"><div class="world-note"><span>✦</span><div><b id="world-note-title">THE HOLLOW IS ALIVE</b><small id="world-note-copy">Traits and temperament are written in every creature's DNA.</small></div></div><div class="stage-actions"><button class="secondary-btn" data-action="archives">▤ DNA ARCHIVE</button><button class="secondary-btn" data-action="breed">♧ BREED</button><button class="primary-btn" data-action="arena">⚔ ENTER ARENA <b>↗</b></button></div></div></section>
49: <aside class="right-panel" id="right-panel"></aside>
50: </main><nav class="mobile-nav"><button data-action="sanctuary">◈<span>Sanctuary</span></button><button data-action="habitat">◉<span>Habitat</span></button><button data-action="profile">◎<span>Profile</span></button></nav><div class="toast" id="toast" role="status"></div><div class="modal-layer hidden" id="modal-layer"><div class="modal" id="modal"></div></div></div>`
51: 
52: const viewport = $('#viewport')
53: world = new World(viewport, { onSelect: selectCreature, onBackground: () => mode === 'habitat' && toast('Select a creature to inspect its genome.') })
54: 
55: function persist() {
56:   try { localStorage.setItem(SAVE, JSON.stringify({ creatures: game.creatures, selected: game.selected, coins: game.coins, food: game.food, wins: game.wins, archives: game.archives })) } catch (e) { console.warn('Save failed', e) }
57:   $('#coins').textContent = game.coins; $('#food').textContent = game.food
58: }
59: function selected() { return game.creatures.find(c => c.id === game.selected) || game.creatures[0] }
60: function toast(text) { const el = $('#toast'); el.textContent = text; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600) }
61: function selectCreature(id) { if (!game.creatures.some(c => c.id === id)) return; game.selected = id; world.setSelected(id); renderRoster(); renderProfile(); persist() }
62: function populateWorld() {
63:   world.clearCreatures()
64:   const spots = [[-2.7,0,.5],[.4,0,-1.5],[2.4,0,1.7],[-1.4,0,3.2],[3.2,0,-2.3],[0,0,2.8]]
65:   game.creatures.forEach((c,i) => world.addCreature(c, { position: spots[i % spots.length], rotation: i * 1.9 }))
66:   world.setSelected(game.selected)
67: }
68: function renderRoster() {
69:   $('#roster').innerHTML = game.creatures.map((c,i) => {
70:     const p = phenotype(c.genome), vitality = Object.values(c.needs).reduce((a,b) => a+b,0)/4
71:     return `<button class="roster-card ${c.id === game.selected ? 'selected' : ''}" data-creature="${esc(c.id)}"><span class="roster-num">0${i+1}</span><span class="roster-avatar" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><i></i></span><span class="roster-info"><b>${esc(c.name)}</b><small>GEN ${c.generation || 0} <i>·</i> ${c.sex === 'F' ? '♀' : '♂'}</small><span class="roster-mini"><i style="width:${vitality}%"></i></span></span><span class="roster-rating">${statsOf(c).power}</span></button>`
72:   }).join('')
73:   $('#roster-count').textContent = String(game.creatures.length).padStart(2,'0'); $('#stage-count').textContent = game.creatures.length
74: }
75: function statBar(label, value, color) { return `<div class="stat-row"><span>${label}</span><div class="bar-track"><i style="width:${clamp(value,0,100)}%;background:${color}"></i></div><b>${Math.round(value)}</b></div>` }
76: function renderProfile() {
77:   const c = selected(); if (!c) return
78:   const p = phenotype(c.genome), stats = statsOf(c), genes = GENES
79:   const body = tab === 'genome' ? renderGenome(c) : tab === 'abilities' ? renderAbilities(c) : renderOverview(c,p,stats)
80:   const combat = mode === 'arena' && battle && !battle.finished && c.id === battle.player.id ? `<section class="combat-actions"><div class="block-heading"><span>CHOOSE YOUR MOVE</span><small>${battle.busy?'TURN IN PROGRESS':'YOUR TURN'}</small></div><div class="combat-grid">${movesFor(c).map(m=>`<button data-move="${m.id}" ${battle.busy?'disabled':''}><b>${m.icon} ${esc(m.name)}</b><small>${m.type==='defend'?`+${Math.abs(m.cost)} STA`:`${Math.max(0,m.cost)} STA · ${Math.round((m.power||0)*20)} PWR`}</small></button>`).join('')}</div></section>` : ''
81:   const trait = p.horns > .62 ? 'HORNED' : p.wings > .62 ? 'WINGED' : p.armor > .62 ? 'ARMORED' : 'ADAPTIVE'
82:   $('#right-panel').innerHTML = `<div class="profile-heading"><div><div class="eyebrow">CREATURE DOSSIER</div><h2>FIELD NOTES</h2></div><button class="icon-btn" data-action="rename" title="Rename creature">···</button></div>
83:   <div class="identity"><div class="identity-art" style="--creature-color:${p.bodyColor};--creature-accent:${p.accentColor}"><span class="art-creature"><i class="art-tail"></i><i class="art-horn"></i><i class="art-eye"></i></span><small>SPECIMEN 0${game.creatures.indexOf(c)+1}</small><b>${p.horns > .72 || p.wings > .75 ? '✦ RARE' : '◈ COMMON'}</b></div><div class="identity-copy"><div class="name-line"><h3>${esc(c.name)}</h3><span>${c.sex === 'F' ? '♀' : '♂'}</span></div><p>${c.generation ? `Generation ${c.generation} · offspring` : 'Foundling · Verdant Hollow'}</p><div class="trait-pills"><span>${esc(p.speciesType.toUpperCase())}</span><span>${p.postureName.toUpperCase()}</span><span>${trait}</span></div><small class="skin-note">${esc(p.skinType)}</small></div></div>
84:   <div class="profile-tabs"><button data-tab="overview" class="${tab==='overview'?'active':''}">OVERVIEW</button><button data-tab="genome" class="${tab==='genome'?'active':''}">GENOME <i>${GENES.length}</i></button><button data-tab="abilities" class="${tab==='abilities'?'active':''}">ABILITIES</button></div><div class="profile-content">${body}</div>${combat}
85:   <div class="profile-footer"><button class="care-btn" data-care="feed"><span>◉</span><b>FEED</b><small>1 NECTAR</small></button><button class="care-btn" data-care="play"><span>♡</span><b>PLAY</b><small>+FUN</small></button><button class="care-btn" data-care="rest"><span>☾</span><b>REST</b><small>+ENERGY</small></button></div>`
86: }
87: function renderOverview(c,p,s) {
88:   const needs = [['Hunger',c.needs.hunger,'🥩'],['Energy',c.needs.energy,'☾'],['Hygiene',c.needs.hygiene,'✧'],['Enrichment',c.needs.fun,'♡']]
89:   return `<section class="panel-block"><div class="block-heading"><span>VITAL SIGNS</span><b class="stable"><i></i> STABLE</b></div>${needs.map(([n,v,icon])=>`<div class="need-row"><span class="need-icon">${icon}</span><span class="need-name">${n}</span><span class="need-track"><i style="width:${v}%;background:${v<28?'#ff7a72':v<55?'#ffc36a':'#77e6bf'}"></i></span><b>${Math.round(v)}%</b></div>`).join('')}</section>
90:   <section class="panel-block"><div class="block-heading"><span>GENETIC POTENTIAL</span><button class="text-action" data-tab="genome">VIEW DNA ↗</button></div>${statBar('ABILITY',s.power,'#d7fa77')}${statBar('BONES',s.bones,'#f2cb77')}${statBar('MOBILITY',s.mobility,'#71d9db')}${statBar('INTELLECT',s.brain,'#b9a4f5')}</section>
91:   <section class="temperament"><span>✺</span><div><b>INSTINCT PROFILE</b><p>${p.brain>.67?'A keen strategist with a curious streak.':p.speed>.67?'Restless and quick to answer a challenge.':p.muscle>.68?'A bold powerhouse who thrives on action.':'An adaptable soul, ready to find its own path.'}</p></div></section><div class="record-line"><span>RECORD <b>${c.wins||0}W — ${Math.max(0,(c.battles||0)-(c.wins||0))}L</b></span><span>AGE <b>${formatAge(c.born)}</b></span></div>`
92: }
93: function renderGenome(c) {
94:   const groups = { frame:'FRAME', limb:'LIMBS', weapon:'ADAPTATIONS', adapt:'ANIMAL ADAPTATIONS', core:'CORE', form:'BODY PLAN', coat:'PIGMENT' }
95:   return `<div class="genome-summary"><small>DNA SEQUENCE<br><b>${dnaSequence(c.genome).slice(0,22)}…</b></small><span>GEN ${c.generation||0}</span></div>${Object.entries(groups).map(([group,label])=>`<section class="gene-group"><div class="gene-group-title">${label}<span>${GENES.filter(g=>g.group===group).length} LOCI</span></div>${GENES.filter(g=>g.group===group).map(g=>{const [a,b]=c.genome?.[g.key]||[0.5,0.5];return `<div class="gene-line" title="${esc(g.desc)}"><span>${g.label}</span><span class="alleles"><i style="width:${a*100}%"></i><i style="width:${b*100}%"></i></span><b>${Math.round((a+b)*50)}</b></div>`}).join('')}</section>`).join('')}`
96: }
97: function renderAbilities(c) {
98:   const moves = movesFor(c)
99:   return `<div class="ability-intro"><span>DNA-EXPRESSED ABILITIES</span><small>${moves.length} UNLOCKED</small></div>${moves.map(m=>`<article class="move-card"><div class="move-icon ${m.type}">${m.icon}</div><div class="move-info"><div><b>${esc(m.name)}</b><span>${m.tag}</span></div><p>${esc(m.desc)}</p><small>${m.type==='defend'?'RECOVERY':`POWER ${Math.round(m.power*34)}`} · COST ${Math.max(0,m.cost)} STA</small></div></article>`).join('')}<div class="ability-note">Abilities emerge from expressed traits. Breed for new combinations.</div>`
100: }
101: function care(action) {
102:   const c=selected()
103:   if(action==='feed') { if(game.food<1)return toast('You are out of nectar. Discover a creature to receive 4 more.'); if(c.needs.hunger>94)return toast(`${c.name} is already full.`); game.food--; c.needs.hunger=clamp(c.needs.hunger+38,0,100); c.needs.energy=clamp(c.needs.energy+5,0,100); toast(`${c.name} enjoyed a nectar fruit.`) }
104:   else if(action==='play') { if(c.needs.energy<12)return toast(`${c.name} is too tired to play. Let them rest.`); c.needs.fun=clamp(c.needs.fun+30,0,100); c.needs.energy=Math.max(0,c.needs.energy-8); toast(`${c.name} had a lovely play session.`) }
105:   else { c.needs.energy=clamp(c.needs.energy+36,0,100); c.needs.hygiene=clamp(c.needs.hygiene+8,0,100); toast(`${c.name} took a restorative nap.`) }
106:   persist(); renderProfile(); renderRoster()
107: }
108: function showModal(content) { $('#modal').innerHTML=content; $('#modal-layer').classList.remove('hidden') }
109: function closeModal() { $('#modal-layer').classList.add('hidden') }
110: function discover() {
111:   if(game.coins<60)return toast('You need 60 shards to discover a creature.')
112:   showModal(`<button class="modal-close" data-action="close" aria-label="Close discovery">×</button><div class="eyebrow">VERDANT HOLLOW · FIELD FIND</div><h2>Shape a new foundling</h2><p>Choose up to three adaptations to guarantee in this creature’s DNA. Every pick grows into a visible body part.</p><div class="adapt-grid">${ADAPTATIONS.map(a=>`<label class="adapt-option"><input type="checkbox" name="adaptation" value="${a.key}"><span class="adapt-icon">${a.icon}</span><span class="adapt-copy"><b>${a.name}</b><small>${a.source}</small><em>${a.note}</em></span><i class="adapt-check">＋</i></label>`).join('')}</div><div class="adapt-footer"><span id="adapt-count">0 / 3 SELECTED</span><small>60 ✧ · +4 NECTAR</small></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="discover-confirm">SEARCH THE HOLLOW ↗</button></div>`)
113: }
114: function discoverConfirm() {
115:   if(game.coins<60)return toast('You need 60 shards to discover a creature.')
116:   const selectedTraits=[...document.querySelectorAll('input[name="adaptation"]:checked')].map(input=>input.value).filter(key=>ADAPTATIONS.some(a=>a.key===key)).slice(0,3)
117:   game.coins-=60
118:   game.food+=4
119:   const c=generateWild()
120:   for(const adaptation of ADAPTATIONS) c.genome[adaptation.key]=selectedTraits.includes(adaptation.key)?[0.88,0.96]:[0.04,0.12]
121:   c.needs=freshNeeds(82)
122:   game.creatures.push(c); game.selected=c.id; closeModal()
123:   if(mode==='habitat') { world.addCreature(c,{position:[(Math.random()-.5)*5,0,(Math.random()-.5)*5]}); world.setSelected(c.id) }
124:   persist(); renderRoster(); renderProfile(); toast(`${c.name} joined with ${selectedTraits.length} adaptation${selectedTraits.length===1?'':'s'}; +4 nectar replenished.`)
125: }
126: function copyGenome(genome) {
127:   return Object.fromEntries(GENES.map(g => {
128:     const alleles = genome?.[g.key] || [0.5, 0.5]
129:     return [g.key, [clamp(Number(alleles[0]) || 0, 0, 1), clamp(Number(alleles[1]) || 0, 0, 1)]]
130:   }))
131: }
132: function archivesDialog() {
